{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "ThH, a morphinan derivative, has very low oral bioavailability in humans, but its bulky additional substituents and altered substitution pattern differ from codeine, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "M6G has poor oral bioavailability and is recommended for intravenous use; its highly polar glucuronide moiety is absent in codeine, so this low-F evidence has limited transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine has very low mean oral systemic availability (0.049 ± 0.032) due to extensive first-pass metabolism, but its benzoquinolizine scaffold differs from codeine's morphinan scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Codeine is a recognized morphinan opioid with established oral bioavailability around 60%, well above the 20% threshold; the low-F analog records are structurally or mechanistically distant and do not override this.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for codeine is present in the supplied records.",
    "Fasted-state-specific codeine bioavailability data are not directly provided.",
    "Most low-F analogs differ substantially in polarity, ionization, scaffold, or metabolic pathway from codeine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

